question.answer:
def calibration_line(site, count, ratio, code):
    return f"{site:<12}|{count:>9,}|{ratio:>7.1%}|{code:#04x}"


def debug_line(reading):
    return f"{reading=}"


def repr_line(reading):
    return f"raw value {reading!r}"


def slugify(filename):
    return "-".join(filename.strip().removesuffix(".txt").lower().split())


def tag_line(tags):
    return ", ".join(tags)
